def resource_to_message_block(resource):
    if resource["mimeType"].startswith("text/"):
        return {"type": "text", "text": resource["text"]}
    if resource["mimeType"].startswith("image/"):
        return {"type": "image", "data": resource["blob"], "mimeType": resource["mimeType"]}
    # fall back to a labeled text block for anything else
    return {"type": "text", "text": f"[unsupported resource type: {resource['mimeType']}]"}

async function attachResource(uri, session) {
  const resource = await session.readResource(uri);
  const block = resourceToMessageBlock(resource);
  return block;
}

const attachment = await attachResource("file:///project/notes/deploy.md", session);
const message = {
  role: "user",
  content: [
    { type: "text", text: "Summarize the deploy steps" },
    attachment
  ]
};

def fetch_with_size_guard(session, uri, max_bytes=200_000):
    meta = session.get_resource_metadata(uri)
    if meta.get("size", 0) > max_bytes:
        return {"truncated": True, "reason": "resource exceeds size limit"}
    return session.read_resource(uri)

class ResourceCache {
  constructor() {
    this.store = new Map();
  }

  async get(uri, session) {
    if (this.store.has(uri)) {
      return this.store.get(uri);
    }
    const resource = await session.readResource(uri);
    const block = resourceToMessageBlock(resource);
    this.store.set(uri, block);
    return block;
  }
}

const cache = new ResourceCache();
const attachment = await cache.get("file:///project/notes/deploy.md", session);

async function getResourceForMessage(uri, session, cache) {
  if (cache.has(uri)) return cache.get(uri);

  const meta = await session.getResourceMetadata(uri);
  if (meta.size > MAX_BYTES) {
    return { type: "text", text: "[resource too large, summary not available]" };
  }

  const resource = await session.readResource(uri);
  const block = resourceToMessageBlock(resource);
  cache.set(uri, block);
  return block;
}

const uri = "file:///project/src/payments.py";
const cached = cache.get(uri);

let content;
if (cached) {
  content = cached;
} else {
  const meta = await session.getResourceMetadata(uri);
  if (meta.size > 200_000) {
    content = { type: "text", text: "[file too large, showing first 200KB only]" };
  } else {
    const resource = await session.readResource(uri);
    content = resourceToMessageBlock(resource);
    cache.set(uri, content);
  }
}

const message = {
  role: "user",
  content: [
    { type: "text", text: "Review this file for bugs" },
    content
  ]
};
